EXPECTED_SHA256 = "e84851887735305c6387ca38a972bebd97ba9cdff7baa7735c0ed89cecf925b5"
KEYS = ("*DENSITY", "*ELASTIC", "*DAMPING", "*CONCRETE DAMAGED PLASTICITY",
        "*CONCRETE COMPRESSION HARDENING", "*CONCRETE TENSION STIFFENING",
        "*CONCRETE COMPRESSION DAMAGE", "*CONCRETE TENSION DAMAGE")
def key(h):
    return h.split(",")[0].strip().upper()
def options(h):
    out = {}
    for item in h.split(",")[1:]:
        k, _, v = item.partition("=")
        k, v = k.strip().upper(), v.strip().upper()
        if k:
            try: v = float(v)
            except ValueError: pass
            out[k] = v
    return out
def read_cards(raw):
    mats = {"C65": {}, "C70": {}}
    name = None
    card = None
    for i, line in enumerate(raw.decode("utf-8-sig", errors="strict").splitlines(), 1):
        s = line.strip()
        if not s or s.startswith("**"): continue
        if s.startswith("*"):
            k = key(s)
            if k == "*MATERIAL":
                name = str(options(s).get("NAME", "")).strip('"').upper()
                if name in mats and mats[name]:
                    raise ValueError("duplicate material: " + name)
            if k in ("*STEP", "*PART", "*ASSEMBLY", "*END ASSEMBLY", "*SURFACE INTERACTION", "*AMPLITUDE", "*BOUNDARY", "*INITIAL CONDITIONS", "*INCLUDE"):
                name = None
            card = None
            if name in mats and k in KEYS:
                if k in mats[name]: raise ValueError("duplicate keyword: " + name + " " + k)
                card = {"header": s, "data": [], "line": i}
                mats[name][k] = card
        elif card is not None:
            card["data"].append(s)
    return mats
def numeric(rows):
    return [[float(x.strip()) if x.strip() else None for x in s.rstrip(", ").split(",")] for s in rows]
def same_rows(a,b,rtol):
    a,b=numeric(a),numeric(b)
    return len(a)==len(b) and all(len(x)==len(y) and all(
        u is None and v is None or u is not None and v is not None and math.isclose(u,v,rel_tol=rtol,abs_tol=1e-12)
        for u,v in zip(x,y)) for x,y in zip(a,b))
def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument("inp",type=Path)
    p.add_argument("--rtol",type=float,default=1e-6)
    p.add_argument("--json",type=Path)
    a=p.parse_args()
    if not 0 <= a.rtol <= 1e-4: p.error("rtol must be 0 to 1e-4")
    raw=a.inp.read_bytes()
    mats=read_cards(raw)
    sha=hashlib.sha256(raw).hexdigest()
    result={"file":str(a.inp),"sha256":sha,"exact_archived_bytes":sha==EXPECTED_SHA256,
            "reference_sha256":EXPECTED_SHA256,"rtol":a.rtol,"native":"NOT_RUN","materials":{}}
    for name, cards in REFERENCE.items():
        result["materials"][name]={}
        for ref in cards:
            k=key(ref["header"])
            if k not in KEYS: continue
            c=mats[name].get(k)
            if c is None: status="MISSING"
            else:
                try:
                    rows=same_rows(ref["data"],c["data"],a.rtol)
                    h=options(ref["header"])==options(c["header"])
                    status="MATCH" if rows and h else "REVIEW_OPTIONS" if rows else "REVIEW_DATA"
                except ValueError: status="REVIEW_NONNUMERIC"
            result["materials"][name][k]={"status":status,"reference_line":ref["line"],
                "reference_rows":len(ref["data"]),"export_line":c["line"] if c else None,
                "export_rows":len(c["data"]) if c else 0,
                "reference_header":ref["header"],"export_header":c["header"] if c else None}
    result["all_compared_cards_match"]=all(c["status"]=="MATCH" for m in result["materials"].values() for c in m.values())
    result["limits"]=["Direct cards only; expand includes before auditing if present.",
                      "Different explicit/default options require manual semantic review.",
                      "Matching inputs do not establish physical validity or solver success."]
    s=json.dumps(result,indent=2,ensure_ascii=False)
    print(s)
    if a.json: 
        if a.json.resolve()==a.inp.resolve(): p.error("JSON cannot overwrite input")
        a.json.write_text(s+"\n",encoding="utf-8")
    return 0 if result["all_compared_cards_match"] else 2
if __name__=="__main__": raise SystemExit(main())
